local function decode(rows,normal)
 local im=Image(64,64,ColorMode.RGB)
 for _,r in ipairs(rows) do
  local y,x,str=r[1],r[2],r[3]
  if normal then
   for i=1,#str,2 do local n=tonumber(str:sub(i,i+1),16);if n>0 then im:drawPixel(x+(i-1)/2,y,N[n]) end end
  else
   for i=1,#str do local n=string.byte(str,i)-65;if n>0 then im:drawPixel(x+i-1,y,P[n]) end end
  end
 end
 return im
end
